with (p/"style.css").open("a",encoding="utf-8") as f:f.write("\n/* Batch 3: retained house controls, shell geometry, ranked cover layering, and bounded scrolling. */\n.app-frame.biblio-explore .row-rail{height:var(--rail-available);max-height:var(--rail-available);display:flex;flex-direction:column}\n.app-frame.biblio-explore .rail-list{max-height:none!important;min-height:0;flex:1}.rail-entry svg{flex:none}\n.app-frame.biblio-explore .book-cover{position:relative;z-index:1}.book-card.ranked .big-rank{z-index:0;top:96px;line-height:1;color:rgba(255,255,255,.16)}\n.shelf-track:has(.ranked){padding-left:30px;gap:26px}.app-frame.phone .book-card.ranked .big-rank{top:62px}\n.book-card .source{position:absolute;z-index:2;top:150px;left:7px;right:7px;font-size:10px;padding-top:12px;background:linear-gradient(transparent,#000b);margin:0}\n.app-frame.phone .book-card .source{top:116px}.book-card:focus .source{display:block}\n.worlds{background:rgba(255,255,255,.07);border:1px solid var(--edge);border-radius:999px;padding:5px;flex-wrap:nowrap}\n.worlds .world{border:0;background:none;white-space:nowrap;font:12px var(--ui);padding:8px 12px}.worlds .world:disabled{opacity:.45}.worlds .world small{font-size:7px}\n.account-circle{position:relative;width:22px!important;height:22px!important;padding:0;border:1px solid #ffffff88!important;color:var(--ink)}\n.account-circle:before{content:\"\";position:absolute;width:5px;height:5px;top:4px;left:7px;border-radius:50%;background:currentColor}.account-circle:after{content:\"\";position:absolute;width:10px;height:6px;bottom:4px;left:5px;border-radius:6px 6px 3px 3px;background:currentColor}\n.batch-world-nav{position:absolute;z-index:20;background:#0a0b10;border-color:var(--edge);display:flex}\n.batch-world-nav button{background:none;border:0;color:var(--muted);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;font:11px var(--ui);min-width:0;flex:1}\n.batch-world-nav button.current{color:var(--gold)}.batch-world-nav img{width:21px;height:21px;opacity:.8}.batch-world-nav button.current img{filter:brightness(0) saturate(100%) invert(84%) sepia(59%) saturate(667%) hue-rotate(347deg) brightness(98%) contrast(91%)}\n.shell-bottom .batch-world-nav{bottom:0;left:0;right:0;height:calc(72px + var(--safe-bottom));padding-bottom:var(--safe-bottom);border-top:1px solid var(--edge)}\n.shell-wide .batch-world-nav{left:0;top:0;bottom:0;width:92px;border-right:1px solid var(--edge);flex-direction:column;justify-content:center}\n.shell-wide .batch-world-nav button{flex:none;height:64px;margin:9px 0;width:100%}\n.biblio-explore.shell-bottom .app-inner{bottom:calc(var(--safe-bottom) + 72px)}.biblio-explore.shell-wide .app-inner{left:calc(var(--safe-left) + 92px)}\n.biblio-explore.shell-wide .worlds{display:none}.biblio-explore .world-tabs button:not(.current){border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.04)}\n.app-frame.phone .row-rail.open{width:clamp(140px,44%,196px)}.app-frame.phone .edit-actions{height:auto;flex-wrap:wrap;gap:5px}\n.app-frame:not(.desktop-host) .search-header>.sys-controls{display:none}.app-frame.search:not(.phone):not(.desktop-host) .search-field{right:var(--pad)}\n.no-results{font:24px var(--display);color:var(--muted);padding:24px 0}\n.app-frame .continue-tile .resume img{width:21px;height:21px;object-fit:contain}.resume{display:grid;place-items:center}\n")
